import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    lines = raw_csv.splitlines(keepends=True)
    start = 0
    while start < len(lines):
        line = lines[start]
        if not line.strip() or line.lstrip().startswith("#"):
            start += 1
        else:
            break

    text = "".join(lines[start:])
    if not text:
        return {"columns": [], "rows": []}

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2**31 - 1)
        candidates = []
        for delimiter in ("\t", ",", ";", "|"):
            reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)
            sample = []
            for row in reader:
                if row:
                    sample.append(row)
                if len(sample) >= 50:
                    break
            if not sample:
                continue
            width = len(sample[0])
            if width > 1:
                matches = sum(len(row) == width for row in sample)
                candidates.append((matches / len(sample), width, delimiter == "\t", delimiter))

        delimiter = max(candidates)[-1] if candidates else "\t"
        reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)
        try:
            columns = next(reader)
        except StopIteration:
            return {"columns": [], "rows": []}

        rows = list(reader)
        width = max([len(columns)] + [len(row) for row in rows])
        used = set(columns)
        while len(columns) < width:
            number = len(columns) + 1
            name = "column_" + str(number)
            while name in used:
                number += 1
                name = "column_" + str(number)
            columns.append(name)
            used.add(name)

        for row in rows:
            row.extend([""] * (width - len(row)))

        return {"columns": columns, "rows": rows}
    finally:
        csv.field_size_limit(previous_limit)
